__NUXT_JSONP__("/th/how-to-apply/others", {data:[{details:{slug:"th",pageTitle:"อื่นๆ | Mentor Language Institute",pageDescription:"ขอบคุณที่ท่านสนใจเข้าเรียนกับ MLI. หน้านี้ใช้สำหรับผู้ที่มีวีซ่าประเภทอื่นๆ นอกจากวีซ่านักเรียนหรือผู้ที่มาจากประเทศ ESTA หรือวีซ่าท่องเที่ยว.",title:"อื่นๆ",image:"\u002Fimages\u002Fhow-to-apply\u002Fapply-others\u002Fapply-others.jpg",subtitle:["ขอบคุณที่ท่านสนใจเข้าเรียนกับ MLI.\u003Cbr \u002F\u003Eหน้านี้ใช้สำหรับผู้ที่มีวีซ่าประเภทอื่นๆ นอกจากวีซ่านักเรียนหรือผู้ที่มาจากประเทศ ESTA หรือวีซ่าท่องเที่ยว.","หากคุณวางแผนที่จะสมัคร MLI โดยไม่ใช้วีซ่านักเรียน (F-1) โปรดดำเนินการลงทะเบียนของคุณจากหน้านี้."],applyOnline:{imageLink:{image:"\u002Fimages\u002Fcommon\u002Fapply-now-th.png",link:"\u002Fth\u002Fadmission"}},applicationSteps:{title:"ขั้นตอนการสมัคร",description:["ขั้นตอนการสมัครจะขึ้นอยู่กับประเทศ สัญชาติ หลักสูตร ประเภทวีซ่า ฯลฯ \u003Cb\u003E เจ้าหน้าที่ของเราจะแนะนำคุณเกี่ยวกับขั้นตอนหลังจากที่คุณสมัคร.\u003C\u002Fb\u003E"]},needHelp:{title:"ต้องการความช่วยเหลือ โปรดติดต่อเรา",description:["- ฉันสามารถเรียนที่ MLI ได้โดยไม่ต้องขอวีซ่าหรือไม่?\u003Cbr \u002F\u003E- เป็นไปได้หรือไม่ที่จะลงทะเบียนเรียนกับวีซ่าประเภทอื่นนอกเหนือวีซ่านักเรียน (F-1)?\u003Cbr \u002F\u003E- ฉันสามารถอยู่ในสหรัฐฯได้นานแค่ไหนโดยไม่มีวีซ่านักเรียน?\u003Cbr \u002F\u003E- ฉันควรเข้าเรียนกี่ชั่วโมงต่อสัปดาห์ที่ MLI เพื่อขอวีซ่านักเรียน?","คำตอบสำหรับคำถามเหล่านี้ได้อธิบายไว้ในเว็บไซต์ของสถานทูตสหรัฐฯหรือบริการด้านพลเมืองและการอพยพของสหรัฐอเมริกา (USCIS).","ถ้าคุณต้องการคำแนะนำก่อนส่งใบสมัคร โปรดยืนยันในเว็บไซต์หรือติดต่อเราได้ตลอดเวลา\u003Cbr \u002F\u003Eเรามีให้บริการถึง 8 ภาษา"]},contactUs:{image:"\u002Fimages\u002Fcommon\u002Fcontact-us-th.jpg",link:"\u002Fth\u002Fcontact",title:"ติดต่อเรา",lists:[{campus:"\u003Cสาขา Westwood\u003E",address:"10880 Wilshire Blvd., Suite #122, Los Angeles, CA 90024",telephone:"โทร: 310-887-0777"},{campus:"\u003Cสาขา Hollywood\u003E",address:"7080 Hollywood Blvd., Suite 314 Los Angeles, CA 90028",telephone:"โทร: 323-870-7102"}]},dir:"\u002Fothers",path:"\u002Fothers\u002Fth",extension:".json",createdAt:"2026-10-22T16:31:30.033Z",updatedAt:"2025-05-26T12:06:27.835Z"}}],fetch:{},mutations:void 0});